          <div className="col-span-1 lg:col-span-4 xl:col-span-3 space-y-6">
            <div className={`bg-white p-6 rounded-2xl shadow-xl border border-white transition-all duration-500 ${state.isAnalyzing ? 'scanning-effect ring-2 ring-blue-500/20' : ''}`}>
              <div className="flex p-1 bg-slate-100 rounded-xl mb-6">
                <button onClick={() => setState(prev => ({ ...prev, mode: AnalysisMode.SINGLE }))} className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${state.mode === AnalysisMode.SINGLE ? 'bg-white shadow-md text-blue-600' : 'text-slate-500 hover:text-slate-700'}`}>Single URL</button>
                <button onClick={() => setState(prev => ({ ...prev, mode: AnalysisMode.BULK }))} className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${state.mode === AnalysisMode.BULK ? 'bg-white shadow-md text-blue-600' : 'text-slate-500 hover:text-slate-700'}`}>Bulk Audit</button>
              </div>

              {state.mode === AnalysisMode.SINGLE ? (
                <div className="relative group">
                  <input type="text" placeholder="https://example.com" value={inputUrl} onChange={(e) => setInputUrl(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-blue-100 focus:border-blue-500 transition-all outline-none" />
                </div>
              ) : (
                <textarea placeholder="Paste URLs (one per line)..." value={bulkInput} onChange={(e) => setBulkInput(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm h-32 focus:ring-2 focus:ring-blue-100 focus:border-blue-500 transition-all outline-none resize-none" />
              )}

              <button 
                disabled={state.isAnalyzing && state.currentProgress < 10}
                onClick={state.isAnalyzing ? handleStopAnalysis : handleStartAnalysis} 
                className={`mt-6 w-full py-4 rounded-xl font-bold text-white shadow-xl transform active:scale-95 transition-all ${state.isAnalyzing ? 'bg-red-500 hover:bg-red-600' : 'bg-gradient-to-r from-blue-600 to-indigo-600 hover:brightness-110'}`}
              >
                {state.isAnalyzing ? 'Abort Operation' : 'Initiate Intelligence Audit'}
              </button>

              {state.isAnalyzing && (
                <div className="mt-6 space-y-2 animate-in fade-in slide-in-from-top-2">
                  <div className="flex justify-between text-[10px] font-bold uppercase tracking-widest text-slate-400">
                    <span>Audit Status</span>
                    <span className="text-blue-600">{state.currentProgress}%</span>
                  </div>
                  <div className="w-full h-2 bg-slate-100 rounded-full overflow-hidden">
                    <div 
                        className="h-full progress-shimmer transition-all duration-500 ease-out rounded-full" 
                        style={{ width: `${state.currentProgress}%` }} 
                    />
                  </div>
                  <div className="flex items-center gap-2 mt-2">
                    <div className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse"></div>
                    <p className="text-[11px] text-slate-500 font-medium italic truncate">{state.progressStatus}</p>
                  </div>
                </div>
              )}
            </div>

            <CriteriaSettings criteria={state.criteria} onChange={(c) => setState(prev => ({ ...prev, criteria: c }))} />
          </div>

          {/* Results Area */}
          <div className="col-span-1 lg:col-span-8 xl:col-span-9">
             {state.results.length === 0 && !state.isAnalyzing ? (
               <div className="h-full flex flex-col items-center justify-center text-slate-400 min-h-[500px] border-2 border-dashed border-slate-200 rounded-[2.5rem] bg-white/40 p-12 text-center animate-in zoom-in-95">
                 <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center mb-6 shadow-inner">
                    <svg className="w-12 h-12 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" /></svg>
                 </div>
                 <h3 className="text-2xl font-bold text-slate-700">Intelligence Ready</h3>
                 <p className="text-slate-500 max-w-xs mx-auto mt-2">Input target URLs to begin multi-vector content auditing and GEO assessment.</p>
               </div>
             ) : (
               <div className="space-y-10">
                 {state.results.map((result, index) => (
                    <div key={index} className="animate-slide-up" style={{ animationDelay: `${index * 0.1}s` }}>
                        <ResultCard result={result} />
                    </div>
                 ))}
                 {/* Fix: use currentTargetsCount instead of targets.length which was out of scope */}
                 {state.isAnalyzing && state.results.length < currentTargetsCount && (
                    <div className="bg-white/50 border border-dashed border-blue-200 rounded-3xl p-12 flex flex-col items-center justify-center gap-4 animate-pulse">
                        <div className="w-10 h-10 border-4 border-blue-100 border-t-blue-500 rounded-full animate-spin"></div>
                        <p className="text-sm font-semibold text-blue-500">Processing next segment...</p>
                    </div>
                 )}
               </div>
             )}
          </div>
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 w-full bg-slate-900 text-slate-400 text-[10px] py-2 px-6 z-50 flex justify-between border-t border-slate-700/50 backdrop-blur-sm">
          <div className="flex gap-4">
            <span className="mono opacity-50">STATUS: {state.isAnalyzing ? 'ACTIVE_AUDIT' : 'IDLE'}</span>
            <span className="mono opacity-50">THREADS: 1</span>
          </div>
          <span className="mono">DEVELOPED_FOR_ANTAKO_NP // v1.2.4-stable</span>
      </footer>

      {state.showAdmin && <AdminPanel settings={state.adminSettings} onSave={(s) => { setState(prev => ({...prev, adminSettings: s})); saveAdminSettings(s); }} onClose={() => setState(prev => ({ ...prev, showAdmin: false }))} />}
      {state.showProxy && <ProxyModal onClose={() => setState(prev => ({ ...prev, showProxy: false }))} onSave={setCustomProxies} initialProxies={customProxies} />}
      {showPasswordModal && <PasswordModal onAuthenticated={() => { setState(prev => ({...prev, isAdminAuthenticated: true, showAdmin: true})); setShowPasswordModal(false); }} onClose={() => setShowPasswordModal(false)} />}
    </div>
  );
};

export default App;
